709	// ItemJourney 凭事项编号汇总它从建立到当前的处理经过：保留事项自身的
710	// 建立、修改、关闭记录，并加入它参与的各次交接（发起交接、逐轮退回、补充后
711	// 重新提交、确认接收或继续跟踪），无须先知道涉及哪些交接编号。
712	// 经过按实际发生时刻排序（带不同时区的时间按同一实际时刻比较）；同一时刻下
713	// 同一交接内保持发起、该轮退回、该轮重新提交、后续处理的先后，不同交接按
714	// 交接编号排列。同一次接收若已出现在事项历史里只展示一次。只读查询，
715	// 不改变事项、交接进度或班次结束时记录。
716	func (svc *Service) ItemJourney(itemID string) (ItemJourney, error) {
717		itemID = clean(itemID)
718		d := &svc.store.data
719		it, _ := findItem(d, itemID)
720		if it == nil {
721			return ItemJourney{}, fmt.Errorf("%w：事项 %s", ErrNotFound, itemID)
722		}
723		j := ItemJourney{Item: *it}
724	
725		// 排序键：先按实际发生时刻（未记录时间的排最后），同一时刻下事项自身
726		// 事件在前，其后按交接编号分组，组内保持生成顺序（发起、逐轮退回、
727		// 该轮重新提交、后续处理）。
728		type keyedEvent struct {
729			ev    JourneyEvent
730			group string // "" 表示事项自身事件，否则为交接编号
731			ord   int    // 同一（时刻、分组）内的先后
732		}
733		var events []keyedEvent
734		seq := 0
735		add := func(ev JourneyEvent, group string) {
736			events = append(events, keyedEvent{ev: ev, group: group, ord: seq})
737			seq++
738		}
739	
740		// received 事件与交接中的接收处理是同一次接收，只展示一次（以交接事件
741		// 展示，信息更全）；匹配不上的旧数据 received 事件仍原样保留。
742		receivedUsed := make([]bool, len(it.Events))
743	
744		hs := append([]Handover(nil), d.Handovers...)
745		sort.Slice(hs, func(i, k int) bool { return hs[i].ID < hs[k].ID })
746		for k := range hs {
747			h := &hs[k]
748			e, _ := findEntry(h, itemID)
749			if e == nil {
750				continue
751			}
752			j.HasHandovers = true
753			j.Results = append(j.Results, EntryView{
754				HandoverID: h.ID,
755				FromShift:  h.FromShiftID,
756				ToShift:    h.ToShiftID,
757				Entry:      *e,
758			})
759	
760			// 发起交接：交接记录本身不记操作人，明确显示未记录，不以班次负责人代替。
761			add(JourneyEvent{
762				At: h.CreatedAt, TimeKnown: !h.CreatedAt.IsZero(),
763				Kind: "handover-init", HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
764			}, h.ID)
765			for _, r := range e.Rounds {
766				add(JourneyEvent{
767					At: r.ReturnedAt, TimeKnown: !r.ReturnedAt.IsZero(),
768					Kind: "return", Operator: r.ReturnOperator,
769					HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
770					RoundSeq: r.Seq, Reason: r.Reason,
771				}, h.ID)
772				if r.ResubmittedAt != nil {
773					add(JourneyEvent{
774						At: *r.ResubmittedAt, TimeKnown: !r.ResubmittedAt.IsZero(),
775						Kind: "resubmit", Operator: r.SupplementOperator,
776						HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
777						RoundSeq: r.Seq, Supplement: r.Supplement,
778						SupplementOperator: r.SupplementOperator, SupplementAt: r.SupplementAt,
779					}, h.ID)
780				}
781			}
782			if e.Status.Received() {
783				kind := "confirm"
784				if e.Status == EntryTracking {
785					kind = "track"
786				}
787				ev := JourneyEvent{
788					Kind: kind, Operator: e.Operator,
789					HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
790					TrackingNote: e.TrackingNote,
791					// 继续跟踪当时指定的后续负责人取自交接记录快照，
792					// 之后修改事项负责人不改变这里的历史值。
793					FollowOwner: e.FollowOwner,
794				}
795				if e.ProcessedAt != nil {
796					ev.At, ev.TimeKnown = *e.ProcessedAt, true
797				}
798				add(ev, h.ID)
799				if e.ProcessedAt != nil {
800					for i := range it.Events {
801						iev := &it.Events[i]
802						if iev.Kind == "received" && !receivedUsed[i] &&
803							iev.At.Equal(*e.ProcessedAt) && iev.Operator == e.Operator {
804							receivedUsed[i] = true
805							break
806						}
807					}
808				}
809			}
810		}
811	
812		// 事项自身历史：建立、修改、关闭原样保留；未被交接接收事件覆盖的
813		// received 事件（旧数据）也保留。
814		for i, iev := range it.Events {
815			if iev.Kind == "received" && receivedUsed[i] {
816				continue
817			}
818			add(JourneyEvent{
819				At: iev.At, TimeKnown: !iev.At.IsZero(),
820				Kind: iev.Kind, Operator: iev.Operator, Detail: iev.Detail,
821			}, "")
822		}
823	
824		sort.SliceStable(events, func(i, k int) bool {
825			a, b := events[i], events[k]
826			if a.ev.TimeKnown != b.ev.TimeKnown {
827				return a.ev.TimeKnown
828			}
829			if a.ev.TimeKnown && !a.ev.At.Equal(b.ev.At) {
830				return a.ev.At.Before(b.ev.At)
831			}
832			if a.group != b.group {
833				return a.group < b.group
834			}
835			return a.ord < b.ord
836		})
837		for _, ke := range events {
838			j.Events = append(j.Events, ke.ev)
839		}
840		return j, nil
841	}
842	
843	// GetHandover 按编号查询交接。
844	func (svc *Service) GetHandover(id string) (Handover, error) {
845		h, _ := findHandover(&svc.store.data, clean(id))
846		if h == nil {
847			return Handover{}, fmt.Errorf("%w：交接 %s", ErrNotFound, id)
848		}
849		return *h, nil
850	}
851	
852	// ListHandovers 返回全部交接记录，按编号排序。
853	func (svc *Service) ListHandovers() []Handover {
854		out := append([]Handover(nil), svc.store.data.Handovers...)
855		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
856		return out
857	}
858	
859	// OverlapNotes 返回涉及指定班次的全部重叠说明。
860	func (svc *Service) OverlapNotes(shiftID string) []OverlapNote {
861		shiftID = clean(shiftID)
862		out := []OverlapNote{}
863		for _, n := range svc.store.data.Notes {
864			if n.ShiftA == shiftID || n.ShiftB == shiftID {
865				out = append(out, n)
866			}
867		}
868		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
869		return out
870	}
871	
872	// ShiftReport 按班次汇总完整事项、关闭情况、接班对象、每项交接当前结果与历次退回/补充说明。
873	// 进行中的班次展示当前事项；已结束班次展示结束时冻结的事项记录，
874	// 旧数据中缺少结束时记录的班次只展示当前事项并标明历史不完整。
875	func (svc *Service) ShiftReport(shiftID string) (ShiftReport, error) {
876		shiftID = clean(shiftID)
877		d := &svc.store.data
878		rep := ShiftReport{Results: map[string][]EntryView{}, LatestItems: map[string]Item{}}
879		sh, _ := findShift(d, shiftID)
880		if sh == nil {
881			return ShiftReport{}, fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
882		}
883		rep.Shift = *sh
884	
885		for _, n := range d.Notes {
886			if n.ShiftA == sh.ID || n.ShiftB == sh.ID {
887				rep.OverlapNotes = append(rep.OverlapNotes, n)
888			}
889		}
890		sort.Slice(rep.OverlapNotes, func(i, j int) bool { return rep.OverlapNotes[i].ID < rep.OverlapNotes[j].ID })
891	
892		switch {
893		case !sh.Closed:
894			// 进行中的班次：事项可继续修改、关闭，展示当前信息。
895			rep.Items = currentItemsOfShift(d, sh.ID)
896		case sh.CloseRecord != nil:
897			// 已结束且有结束时记录：展示冻结的结束时信息，并对照最新状态。
898			rep.ItemsAtClose = true
899			rep.CloseItems = append([]CloseItemSnapshot(nil), sh.CloseRecord.Items...)
900			sort.Slice(rep.CloseItems, func(i, j int) bool { return rep.CloseItems[i].ItemID < rep.CloseItems[j].ItemID })
901			for _, s := range rep.CloseItems {
902				if it, _ := findItem(d, s.ItemID); it != nil {
903					rep.LatestItems[s.ItemID] = *it
904				}
905			}
906		default:
907			// 旧数据：结束时未留下记录，只能展示当前信息，不能宣称是结束时事实。
908			rep.HistoryIncomplete = true
909			rep.Items = currentItemsOfShift(d, sh.ID)
910		}
911		sort.Slice(rep.Items, func(i, j int) bool { return rep.Items[i].ID < rep.Items[j].ID })
912	
913		for i := range d.Handovers {
914			h := &d.Handovers[i]
915			involved := h.FromShiftID == sh.ID || h.ToShiftID == sh.ID
916			if !involved {
917				continue
918			}
919			if h.FromShiftID == sh.ID {
920				cp := *h
921				rep.Outgoing = &cp
922			}
923			if h.ToShiftID == sh.ID {
924				rep.Incoming = append(rep.Incoming, *h)
925			}
926			for j := range h.Entries {
927				rep.Results[h.Entries[j].ItemID] = append(rep.Results[h.Entries[j].ItemID], EntryView{
928					HandoverID: h.ID,
929					FromShift:  h.FromShiftID,
930					ToShift:    h.ToShiftID,
931					Entry:      h.Entries[j],
932				})
933			}
934		}
935		sort.Slice(rep.Incoming, func(i, j int) bool { return rep.Incoming[i].ID < rep.Incoming[j].ID })
936		for k := range rep.Results {
937			sort.Slice(rep.Results[k], func(i, j int) bool { return rep.Results[k][i].HandoverID < rep.Results[k][j].HandoverID })
938		}
939		return rep, nil
940	}
