214		if e.ProcessedAt == nil {
215			b.WriteString("  最后处理：尚未处理（等待接班人处理）\n")
216		} else {
217			fmt.Fprintf(&b, "  最后处理：操作人=%s 时间=%s\n", dashIfEmpty(e.Operator), fmtTimePtr(e.ProcessedAt))
218		}
219		if e.Status == EntryTracking || e.TrackingNote != "" {
220			fmt.Fprintf(&b, "  跟踪说明：%s\n", dashIfEmpty(e.TrackingNote))
221			fmt.Fprintf(&b, "  跟踪后续负责人：%s\n", dashIfEmpty(e.FollowOwner))
222		}
223		for _, r := range e.Rounds {
224			fmt.Fprintf(&b, "  第%d次退回：%s 操作人=%s 原因=%s\n",
225				r.Seq, fmtTime(r.ReturnedAt), r.ReturnOperator, r.Reason)
226			if r.Supplement != "" {
227				fmt.Fprintf(&b, "    补充说明：%s 补充人=%s 补充时间=%s\n",
228					r.Supplement, dashIfEmpty(r.SupplementOperator), fmtTimePtr(r.SupplementAt))
229			}
230			if r.ResubmittedAt != nil {
231				fmt.Fprintf(&b, "    已重新提交：%s\n", fmtTime(*r.ResubmittedAt))
232			}
233		}
234		return b.String()
